def maxSubarrayBounds(nums):
    cur = nums[0]
    start = 0
    best = (-cur, 0, 0)
    for i in range(1, len(nums)):
        if cur < 0:
            cur = nums[i]
            start = i
        else:
            cur += nums[i]
        cand = (-cur, start, i)
        if cand < best:
            best = cand
    return [-best[0], best[1], best[2]]
